<script setup>
import {ref,onMounted,computed} from 'vue';
const user=ref(null),email=ref('buyer@example.test'),password=ref('password'),tab=ref('Dashboard'),data=ref({}),error=ref(''),message=ref(''),busy=ref(false);
const tabs=['Dashboard','Items','Purchase Orders','Goods Receipts','QC Inspections','Stock','Invoices','Audit'];
const po=ref({supplier_id:'',warehouse_id:'',order_date:new Date().toISOString().slice(0,10),expected_date:'',lines:[{item_id:'',quantity:300,unit_price:100,tax_rate:18}]});
const grn=ref({purchase_order_id:'',received_date:new Date().toISOString().slice(0,10),lines:[{purchase_order_item_id:'',lots:[{lot_number:'LOT-001',quantity:300,manufactured_at:'',expires_at:''}]}]});
const invoice=ref({invoice_number:'INV-001',purchase_order_id:'',invoice_date:new Date().toISOString().slice(0,10),lines:[{goods_receipt_lot_id:'',quantity:1}]});
const newItem=ref({item_code:'ITEM002',name:'Demo Item',category:'Raw Material',uom:'PCS',qc_required:true,min_lot_size:1,max_lot_size:5000,parameters:[{parameter_name:'Height',min_value:1,max_value:20,unit:'mm'}],rules:[{min_quantity:1,max_quantity:100,sample_count:2},{min_quantity:101,max_quantity:500,sample_count:5},{min_quantity:501,max_quantity:1000,sample_count:10},{min_quantity:1001,max_quantity:null,sample_count:15}]});
const lotQty=ref(80),sampleResult=ref(null),selectedItem=ref('');const measurement=ref({});
const activePO=computed(()=>data.value.purchase_orders?.find(p=>p.id==grn.value.purchase_order_id));
function csrf(){return decodeURIComponent((document.cookie.match(/(?:^|; )XSRF-TOKEN=([^;]*)/)||[])[1]||'')}
async function api(path,method='GET',body){const res=await fetch('/api'+path,{method,credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-XSRF-TOKEN':csrf()},...(body!==undefined?{body:JSON.stringify(body)}:{})});const json=await res.json().catch(()=>({}));if(!res.ok){let details=json.errors?Object.values(json.errors).flat().join('; '):'';throw new Error(details||json.message||'HTTP '+res.status)}return json}
async function run(fn){busy.value=true;error.value='';message.value='';try{await fn();message.value='Saved successfully';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){try{user.value=await api('/me');data.value=await api('/overview');if(!selectedItem.value)selectedItem.value=data.value.items?.[0]?.id||''}catch(e){user.value=null}}
async function login(){await run(async()=>{user.value=await api('/login','POST',{email:email.value,password:password.value})})}
async function logout(){await run(async()=>{await api('/logout','POST',{});user.value=null;data.value={}})}
async function calc(){await run(async()=>{sampleResult.value=await api(`/items/${selectedItem.value}/qc-samples?lot_quantity=${lotQty.value}`)})}
async function createPO(){await run(async()=>{await api('/purchase-orders','POST',po.value);tab.value='Purchase Orders'})}
async function createGRN(){await run(async()=>{await api('/goods-receipts','POST',grn.value)})}
async function createInvoice(){await run(async()=>{await api('/supplier-invoices','POST',invoice.value)})}
function start(lot){run(async()=>{await api(`/lots/${lot.id}/inspect`,'POST',{})})}
function buildReadings(i){let result=[];for(let n=1;n<=i.required_samples;n++){let values={};for(const p of i.parameters_snapshot)values[p.name]=Number(measurement.value[i.id+'-'+n+'-'+p.name]??15);result.push({sample_number:n,values})}return {readings:result}}
function act(path,body={}){run(async()=>{await api(path,'POST',body)})}
const itemName=id=>data.value.items?.find(i=>i.id===id)?.name||id;
onMounted(load);
</script>
<template>
<div v-if="!user" class="card" style="max-width:420px;margin:10vh auto"><h1>ERP Purchase + QC</h1><p class="muted">Sign in using a demo account from README.md.</p><label>Email<input v-model="email"></label><label>Password<input v-model="password" type="password"></label><button @click="login" :disabled="busy">Sign in</button><div v-if="error" class="error">{{error}}</div></div>
<div v-else class="layout"><aside class="sidebar"><h2>ERP Assessment</h2><p>{{user.name}}<br><span class="small">{{user.role}}</span></p><button v-for="t in tabs" :key="t" :class="{active:tab===t}" @click="tab=t">{{t}}</button><hr><button @click="logout">Log out</button></aside>
<main class="main"><h1>{{tab}}</h1><div v-if="error" class="error">{{error}}</div><div v-if="message" class="success">{{message}}</div>
<section v-if="tab==='Dashboard'" class="grid"><div v-for="[name,count] in [['Items',data.items?.length],['Purchase Orders',data.purchase_orders?.length],['GRNs',data.goods_receipts?.length],['Lots',data.lots?.length],['QC Inspections',data.inspections?.length],['Invoices',data.invoices?.length]]" :key="name" class="card"><div class="muted">{{name}}</div><h1>{{count||0}}</h1></div></section>
<template v-if="tab==='Items'"><div class="card"><h2>Item Master</h2><div class="scroll"><table><tr><th>Code</th><th>Name</th><th>UOM</th><th>QC</th><th>Parameters</th><th>Sampling</th></tr><tr v-for="i in data.items" :key="i.id"><td>{{i.item_code}}</td><td>{{i.name}}</td><td>{{i.uom}}</td><td>{{i.qc_required?'Yes':'No'}}</td><td><div v-for="p in i.qc_parameters" :key="p.id">{{p.parameter_name}}: {{p.min_value}}–{{p.max_value}} {{p.unit}}</div></td><td><div v-for="r in i.sampling_rules" :key="r.id">{{r.min_quantity}}–{{r.max_quantity??'∞'}}: {{r.sample_count}}</div></td></tr></table></div></div>
<div class="card"><h2>QC Sample Calculator</h2><div class="row"><label>Item<select v-model="selectedItem"><option v-for="i in data.items" :value="i.id">{{i.item_code}}</option></select></label><label>Lot Quantity<input type="number" v-model.number="lotQty"></label><button @click="calc">Calculate</button></div><h2 v-if="sampleResult">{{sampleResult.required_samples}} samples</h2></div>
<div class="card"><h2>Create Item</h2><div class="grid"><label>Code<input v-model="newItem.item_code"></label><label>Name<input v-model="newItem.name"></label><label>Category<input v-model="newItem.category"></label><label>UOM<input v-model="newItem.uom"></label><label>Minimum Lot<input type="number" v-model.number="newItem.min_lot_size"></label><label>Maximum Lot<input type="number" v-model.number="newItem.max_lot_size"></label></div><label><span>QC required</span><input type="checkbox" v-model="newItem.qc_required"></label><h3>QC parameters</h3><div class="row" v-for="p in newItem.parameters"><input v-model="p.parameter_name" placeholder="Parameter"><input type="number" v-model.number="p.min_value" placeholder="Min"><input type="number" v-model.number="p.max_value" placeholder="Max"><input v-model="p.unit" placeholder="Unit"></div><button @click="newItem.parameters.push({parameter_name:'',min_value:1,max_value:20,unit:'mm'})">Add parameter</button><h3>Sampling rules</h3><div class="row" v-for="r in newItem.rules"><label>From<input type="number" v-model.number="r.min_quantity"></label><label>To (blank = unlimited)<input type="number" :value="r.max_quantity??''" @input="r.max_quantity=$event.target.value===''?null:Number($event.target.value)"></label><label>Samples<input type="number" v-model.number="r.sample_count"></label></div><button @click="newItem.rules.push({min_quantity:1,max_quantity:null,sample_count:1})">Add rule</button> <button @click="act('/items',newItem)">Save item</button></div></template>
<template v-if="tab==='Purchase Orders'"><div class="card"><h2>Create Purchase Order</h2><div class="grid"><label>Supplier<select v-model.number="po.supplier_id"><option value="">Choose</option><option v-for="s in data.suppliers" :value="s.id">{{s.name}}</option></select></label><label>Warehouse<select v-model.number="po.warehouse_id"><option value="">Choose</option><option v-for="w in data.warehouses" :value="w.id">{{w.name}}</option></select></label><label>Order Date<input type="date" v-model="po.order_date"></label><label>Expected Date<input type="date" v-model="po.expected_date"></label></div><div class="row" v-for="l in po.lines"><label>Item<select v-model.number="l.item_id"><option value="">Choose</option><option v-for="i in data.items" :value="i.id">{{i.name}}</option></select></label><label>Quantity<input type="number" v-model.number="l.quantity"></label><label>Unit Price<input type="number" v-model.number="l.unit_price"></label><label>GST %<input type="number" v-model.number="l.tax_rate"></label></div><button @click="po.lines.push({item_id:'',quantity:1,unit_price:0,tax_rate:18})">Add line</button> <button @click="createPO">Create PO</button></div>
<div class="card scroll"><h2>Purchase Orders</h2><table><tr><th>PO</th><th>Status</th><th>Total</th><th>Lines</th><th>Actions</th></tr><tr v-for="p in data.purchase_orders"><td>{{p.po_number}}</td><td>{{p.status}}</td><td>{{p.total}}</td><td><div v-for="l in p.lines">{{itemName(l.item_id)}} × {{l.quantity}}</div></td><td><button v-if="p.status==='draft'" @click="act(`/purchase-orders/${p.id}/submit`)">Submit</button> <button v-if="p.status==='submitted'" @click="act(`/purchase-orders/${p.id}/approve`)">Approve</button></td></tr></table></div></template>
<template v-if="tab==='Goods Receipts'"><div class="card"><h2>Create GRN</h2><label>Approved PO<select v-model.number="grn.purchase_order_id"><option value="">Choose</option><option v-for="p in data.purchase_orders?.filter(x=>['approved','partially_received'].includes(x.status))" :value="p.id">{{p.po_number}}</option></select></label><label>Received Date<input type="date" v-model="grn.received_date"></label><div v-for="line in grn.lines" class="card"><label>PO Item<select v-model.number="line.purchase_order_item_id"><option value="">Choose</option><option v-for="l in activePO?.lines" :value="l.id">{{itemName(l.item_id)}} — ordered {{l.quantity}}</option></select></label><div v-for="lot in line.lots" class="row"><label>Lot Number<input v-model="lot.lot_number"></label><label>Quantity<input type="number" v-model.number="lot.quantity"></label><label>Manufactured<input type="date" v-model="lot.manufactured_at"></label><label>Expires<input type="date" v-model="lot.expires_at"></label></div><button @click="line.lots.push({lot_number:'',quantity:1,manufactured_at:'',expires_at:''})">Add lot</button></div><button @click="grn.lines.push({purchase_order_item_id:'',lots:[{lot_number:'',quantity:1,manufactured_at:'',expires_at:''}]})">Add PO line</button> <button @click="createGRN">Create GRN</button></div><div class="card"><h2>Received Lots</h2><table><tr><th>Lot</th><th>Qty</th><th>QC</th></tr><tr v-for="l in data.lots"><td>{{l.lot_number}}</td><td>{{l.quantity}}</td><td>{{l.qc_status}}</td></tr></table></div></template>
<template v-if="tab==='QC Inspections'"><div class="card"><h2>Lots waiting for QC</h2><table><tr><th>Lot</th><th>Qty</th><th>Status</th><th>Action</th></tr><tr v-for="l in data.lots"><td>{{l.lot_number}}</td><td>{{l.quantity}}</td><td>{{l.qc_status}}</td><td><button v-if="l.qc_status==='hold' && !l.inspections?.some(i=>['draft','submitted','passed'].includes(i.status))" @click="start(l)">Start QC</button></td></tr></table></div><div v-for="i in data.inspections" :key="i.id" class="card"><h2>Inspection #{{i.id}} — Lot #{{i.goods_receipt_lot_id}} <span class="pill">{{i.status}}</span></h2><p>{{i.required_samples}} samples · {{i.parameters_snapshot.map(p=>p.name).join(', ')}}</p><template v-if="i.status==='draft'"><div v-for="n in i.required_samples" class="card"><b>Sample {{n}}</b><div class="row"><label v-for="p in i.parameters_snapshot" :key="p.name">{{p.name}} ({{p.min}}–{{p.max}} {{p.unit}})<input type="number" step="0.001" v-model.number="measurement[i.id+'-'+n+'-'+p.name]" placeholder="15"></label></div></div><button @click="act(`/qc-inspections/${i.id}/measurements`,buildReadings(i))">Save all measurements</button> <button @click="act(`/qc-inspections/${i.id}/submit`)">Submit QC</button><p class="muted small">Save measurements before submitting. Blank inputs use the demo value 15.</p></template><div v-if="i.status==='submitted'"><button @click="act(`/qc-inspections/${i.id}/approve`,{reason:'Out-of-range measurement'})">Approve / evaluate QC</button></div><div v-for="s in i.samples" class="small">Sample {{s.sample_number}}: {{s.results.map(r=>r.parameter_name+'='+r.measured_value+(r.passed?' ✓':' ✗')).join(', ')}}</div></div></template>
<template v-if="tab==='Stock'"><div class="card"><h2>Stock movements</h2><table><tr><th>Lot</th><th>Item</th><th>From</th><th>To</th><th>Qty</th><th>Reference</th></tr><tr v-for="m in data.stock_movements"><td>{{m.goods_receipt_lot_id}}</td><td>{{itemName(m.item_id)}}</td><td>{{m.from_bucket||'External'}}</td><td>{{m.to_bucket}}</td><td>{{m.quantity}}</td><td>{{m.reference}}</td></tr></table></div></template>
<template v-if="tab==='Invoices'"><div class="card"><h2>Create Supplier Invoice</h2><div class="grid"><label>Supplier Invoice Number<input v-model="invoice.invoice_number"></label><label>Purchase Order<select v-model.number="invoice.purchase_order_id"><option value="">Choose</option><option v-for="p in data.purchase_orders" :value="p.id">{{p.po_number}}</option></select></label><label>Invoice Date<input type="date" v-model="invoice.invoice_date"></label></div><div v-for="l in invoice.lines" class="row"><label>Accepted Lot<select v-model.number="l.goods_receipt_lot_id"><option value="">Choose</option><option v-for="lot in data.lots?.filter(x=>x.qc_status==='passed')" :value="lot.id">{{lot.lot_number}} — {{lot.quantity}}</option></select></label><label>Qty<input type="number" v-model.number="l.quantity"></label></div><button @click="invoice.lines.push({goods_receipt_lot_id:'',quantity:1})">Add line</button> <button @click="createInvoice">Create Invoice</button></div><div class="card"><h2>Invoices</h2><table><tr><th>Number</th><th>PO</th><th>Total</th><th>Status</th></tr><tr v-for="i in data.invoices"><td>{{i.invoice_number}}</td><td>{{i.purchase_order_id}}</td><td>{{i.total}}</td><td>{{i.status}}</td></tr></table></div></template>
<template v-if="tab==='Audit'"><div class="card"><h2>Audit history</h2><table><tr><th>When</th><th>Action</th><th>Entity</th><th>ID</th></tr><tr v-for="a in data.audit"><td>{{a.created_at}}</td><td>{{a.action}}</td><td>{{a.entity}}</td><td>{{a.entity_id}}</td></tr></table></div></template>
</main></div>
</template>
